new EffectCoordinator(new FileEffectJournal(path.join(runRoot, 'effects.jsonl')), () => new Date(), {
    requested: (request, executionMode) => append('effect.requested', request, { executionMode, capability: request.capability, operation: request.operation, resource: request.resource }),
    accepted: (request, executionMode) => append('effect.accepted', request, { executionMode }),
    completed: (request, receipt, executionMode) => append(receipt.status === 'completed' ? 'effect.completed' : 'effect.failed', request,
      receipt.status === 'completed' ? { executionMode, adapter: receipt.adapter, result: auditResult(receipt.result ?? {}) } : { executionMode, adapter: receipt.adapter, error: receipt.error ?? {} }),
  }, new FileResourceLockManager(path.join(platform.storageRoot, 'resource-locks')), platform.effectLockTtlMs)

new core.EffectCoordinator(
  confidentialJournal,
  () => new Date('2026-07-25T22:00:00Z'),
  {
    requested(request) { confidentialAudit.push(['requested', request]); },
    accepted(request) { confidentialAudit.push(['accepted', request]); },
    completed(request, receipt) { confidentialAudit.push(['completed', request, receipt]); },
  },
  new core.MemoryResourceLockManager(), 300_000,
)

new core.EffectCoordinator(
  new core.MemoryEffectJournal(),
  () => new Date('2026-07-25T22:00:00Z'),
  {
    requested(request) { confidentialFailureAudit.push(['requested', request]); },
    accepted(request) { confidentialFailureAudit.push(['accepted', request]); },
    completed(request, receipt) { confidentialFailureAudit.push(['completed', request, receipt]); },
  },
  new core.MemoryResourceLockManager(), 300_000,
)

